def plant_an_internal_version_name_in_a_heading() -> Result:
    """Paint the blend's version back beside the Record page's heading.

    OPERATOR QUESTION 19, ruled 2026-09-27 (third set): "fixed in the board:
    headings in plain words; internal version names only in a tooltip". Built
    by the board merge (2026-09-29). The Record page's "Priced, and against the
    close" carried the blend's name "b1" in a `<small>` the renderer filled
    from `priced.blend_version`, on every sport. Planted four ways, each of
    which the scans must name: the heading with the name written into it, the
    renderer painting a version field as visible text, a correction's number
    said in words on a line a reader sees, and the page's own words with a
    version name in them -- while the same name in a TOOLTIP (a `title`, or a
    board tooltip) must pass. And the gate's step 2 must make the call (read
    from its syntax tree, as question 20's and question 15's are pinned).
    """
    guard = "audit.heading_words_faults, audit.version_painted_faults"
    violation = "an internal version name beside a heading"
    web = config.PACKAGE_ROOT / "web"
    html = (web / "index.html").read_text(encoding="utf-8")
    js = (web / "app.js").read_text(encoding="utf-8")
    shipped = audit.heading_words_faults(html) + audit.version_painted_faults(js)
    if shipped:
        return Result("PLAIN WORDS", violation, guard, False,
                      "the shipped page already fails; fix that before "
                      "trusting this planting: " + shipped[0])
    heading = '<h3 id="priced-heading">Priced, and against the close</h3>'
    painter = "if (heading && priced) heading.title = priced.version_tip || '';"
    if html.count(heading) != 1 or js.count(painter) != 1:
        return Result("PLAIN WORDS", violation, guard, False,
                      "the priced heading is no longer written the way this "
                      "planting expects; re-point it")
    missed, first = [], None
    written = audit.heading_words_faults(html.replace(
        heading, '<h3 id="priced-heading">Priced, and against the close '
                 f'<small>{config.PRICED_VERSION}</small></h3>'))
    if not written:
        missed.append("a heading with the blend's name written into it passed")
    painted = audit.version_painted_faults(js.replace(
        painter, "if (heading && priced) heading.textContent = priced.blend_version || '';"))
    if not painted:
        missed.append("the renderer painting `blend_version` as the heading's text passed")
    said = audit.plain_words_violations(
        "Version 8 has been withdrawn since Tuesday 29 September")
    if not said:
        missed.append("a correction's number in words on a line a reader sees passed")
    ranker = audit.plain_words_violations(
        f"Did the ordering earn its place {config.RANKER_VERSION}")
    if not ranker:
        missed.append("the ordering's name beside its heading passed")
    # THE TOOLTIP IS WHERE THE NAME BELONGS, and it must pass there.
    if audit.plain_words_violations(
            f"Version {config.PRICED_VERSION}: the blend.", in_a_tooltip=True):
        missed.append("a version name in a tooltip was refused")
    titled = audit.heading_words_faults(html.replace(
        heading, f'<h3 id="priced-heading" title="Version {config.PRICED_VERSION}">'
                 'Priced, and against the close</h3>'))
    if titled:
        missed.append(f"a version name in a heading's title was refused: {titled[0]}")
    first = (written or painted or said or [None])[0]
    import ast as _ast
    gate = Path(audit.__file__).resolve().parents[1] / "tools" / "verify.py"
    step = next((node for node in _ast.parse(gate.read_text(encoding="utf-8")).body
                 if isinstance(node, _ast.FunctionDef) and node.name == "step_2_guards"),
                None)
    if step is None or not any(
            isinstance(node, _ast.Attribute)
            and node.attr == "check_headings_are_plain_words"
            and isinstance(node.value, _ast.Name) and node.value.id == "audit"
            for node in _ast.walk(step)):
        missed.append("the gate's step 2 does not call "
                      "`audit.check_headings_are_plain_words`")
    if missed:
        return Result("PLAIN WORDS", violation, guard, False,
                      "NOT CAUGHT - " + " | ".join(missed))
    return Result("PLAIN WORDS", violation, guard, True, first or "")


def plant_a_chance_on_a_live_board_row() -> Result:
    """Put a chance and a tier chip on a live row of the board.

    LIVE TAB, RE-HOMED BY THE BOARD MERGE (2026-09-29). The Live tab left with
    the old Picks route; a game being played is a row on Games now, and the
    promise travels with it: the row shows the game and the pregame figure
    with its word, and nothing else. The board built a live row's block with
    its chance in the payload (`prob`, `prob_words`) and drew neither; this
    plants them, and a tier chip, on the pick and on a question behind it,
    and on a live prop tile, and expects each named.
    """
    from gridiron import audit as _audit

    planted = {"board": {
        "games": [{"state": "live", "pick_label_words": "Model's pick · pregame",
                   "pick": {"state": "live", "pregame_words": "pregame 61%",
                            "prob": 0.61, "prob_words": "61%"},
                   "questions": [{"state": "live", "tier_chip": "STRONG"}]}],
        "props": {"tiles": [{"state": "live", "prob_words": "58%"}]}}}
    faults = _audit.live_tab_faults(planted)
    wanted = ("board.games[0].pick carries 'prob'",
              "board.games[0].pick carries 'prob_words'",
              "board.games[0].questions[0] carries 'tier_chip'",
              "board.props.tiles[0] is live and carries 'prob_words'")
    absent = [w for w in wanted if not any(w in f for f in faults)]
    try:
        _audit.check_the_live_tab_shows_only_the_game(planted)
        refused = False
    except _audit.LawViolation:
        refused = True
    if absent or not refused:
        return Result(LAW_CARDS, "a chance and a tier chip on a live board row",
                      "audit.live_tab_faults", False,
                      f"NOT CAUGHT - {absent or 'the check raised nothing'}")
    return Result(LAW_CARDS, "a chance and a tier chip on a live board row",
                  "audit.live_tab_faults", True, faults[0])


def plant_another_states_label_on_a_live_board_row() -> Result:
    """Let a settled state's label follow a game into play on the board.

    LIVE TAB's second half, re-homed (2026-09-29): a heading belonging to
    another group on Live is, on the board, a live row whose pick is labelled
    for another state -- "won", or the plain label of an upcoming pick.
    """
    from gridiron import audit as _audit

    caught = []
    for label in ("Model's pick · won", "Model's pick"):
        planted = {"board": {"games": [{
            "state": "live", "pick_label_words": label,
            "pick": {"state": "live", "pregame_words": "pregame 61%"},
            "questions": []}]}}
        faults = _audit.live_tab_faults(planted)
        caught.append(bool(faults) and "followed the game into play" in faults[0])
    if not all(caught):
        return Result(LAW_CARDS, "another state's label on a live board row",
                      "audit.live_tab_faults", False,
                      f"NOT CAUGHT - {caught}")
    return Result(LAW_CARDS, "another state's label on a live board row",
                  "audit.live_tab_faults", True,
                  "a live row labelled for another state is refused by name")


def _step_2_calls(name: str) -> bool:
    """Does the gate's step 2 make the call, read from its syntax tree (as
    question 15's and question 20's plantings pin theirs)?"""
    import ast as _ast

    gate = Path(audit.__file__).resolve().parents[1] / "tools" / "verify.py"
    step = next((node for node in _ast.parse(gate.read_text(encoding="utf-8")).body
                 if isinstance(node, _ast.FunctionDef) and node.name == "step_2_guards"),
                None)
    return step is not None and any(
        isinstance(node, _ast.Attribute) and node.attr == name
        and isinstance(node.value, _ast.Name) and node.value.id == "audit"
        for node in _ast.walk(step))


def plant_a_board_count_counting_a_bet_twice() -> Result:
    """Count a bet twice on the board, pool its forecasters, or head Results'
    settled tiles with another set's count.

    THE MERGE'S PROVER (2026-09-29), each measured on the merged board before
    it was fixed: a taken prop is on its game's row and is a tile, and My day
    read both -- one tap, two chips, "2 taken"; a row said "4 questions on
    this game" over three of the model's and one of the reasoning pass's, the
    pooled count operator questions 14 and 22 took off every other panel; and
    Results drew every question on every finished row, both forecasters',
    under the Today block's "Settled -- 15 questions". Planted in the board's
    own shapes, each must be named; the fixed shapes must pass; and the
    gate's step 2 must make the call on every sport's slate.
    """
    from gridiron import audit as _audit, language as _language

    guard = "audit.board_count_faults"
    violation = "a bet counted twice or pooled across forecasters on the board"

    def row(blocks):
        counts: dict = {}
        for b in blocks:
            counts[b["forecaster"]] = counts.get(b["forecaster"], 0) + 1
        return {"state": "final", "questions": blocks, "questions_n": counts,
                "questions_words": _language.game_questions_words(counts, "statistical")}

    prop = {"prediction_id": 7, "forecaster": "statistical", "taken": True}
    spread = {"prediction_id": 8, "forecaster": "statistical", "taken": False}
    theirs = {"prediction_id": 9, "forecaster": "llm", "taken": False}
    good = {"forecaster": "statistical",
            "today": {"settled": [{"prediction_id": 7}, {"prediction_id": 8}]},
            "board": {"games": [row([prop, spread, theirs])],
                      "props": {"tiles": [dict(prop)]},
                      "my_day": {"n": 1, "entries": [{"prediction_id": 7}]},
                      "settled_ids": [7, 8]}}
    missed, first = [], None
    shipped = _audit.board_count_faults(good)
    if shipped:
        missed.append("the fixed shapes are refused: " + shipped[0])
    forms = {
        "one taken prop entered from its row and from its tile": dict(
            good, board=dict(good["board"], my_day={
                "n": 2, "entries": [{"prediction_id": 7}, {"prediction_id": 7}]})),
        "a row's count over both forecasters under 'question'": dict(
            good, board=dict(good["board"], games=[dict(
                row([prop, spread, theirs]),
                questions_words=_language.counted(3, "question") + " on this game")])),
        "a row's count carrying no forecaster": dict(
            good, board=dict(good["board"], games=[dict(
                row([prop, spread, theirs]), questions_n=3)])),
        "Results' settled tiles every finished question, both forecasters'": dict(
            good, board=dict(good["board"], settled_ids=[7, 8, 9])),
        "a My day count stating another number than its chips": dict(
            good, board=dict(good["board"], my_day={
                "n": 2, "entries": [{"prediction_id": 7}]})),
    }
    for name, planted in forms.items():
        faults = _audit.board_count_faults(planted)
        if not faults:
            missed.append(f"{name} passed")
        elif first is None:
            first = faults[0]
    try:
        _audit.check_the_board_counts_each_bet_once(forms[next(iter(forms))])
        missed.append("the check raised nothing on the doubled My day")
    except _audit.LawViolation:
        pass
    if not _step_2_calls("check_the_board_counts_each_bet_once"):
        missed.append("the gate's step 2 does not call "
                      "`audit.check_the_board_counts_each_bet_once`")
    if missed:
        return Result(LAW_CARDS, violation, guard, False, "NOT CAUGHT - " + " | ".join(missed))
    return Result(LAW_CARDS, violation, guard, True, first or "")


def plant_a_board_row_priced_off_the_other_side() -> Result:
    """Show a priced row's stored chance beside the price and payout of the
    side its question does not name.

    THE MERGE'S PROVER (2026-09-29). GRIDIRON_REPAIR item 3: the card's model
    chip reads the entry's corrected `fair_value` (a correction in force by
    its own row, operator question 32); and 2026-09-07's wrong-side rule: a
    price row is about the side the question names. The merge read
    `fair_value` from a Today card that never carried it, so a priced row
    showed the stored chance; and it drew the claim's fixed proposition's
    price and payout under a question naming the other side. On this world
    -- the away side at 57%, a 48.5c home price, a correction in force making
    the home side 53.58% -- the merged row read 57% beside 48c and 2.06x where
    the card's chip read 46c against 52c. Planted three ways on the real
    payload: the card without the two numbers (the merge's shape), the price
    left on the proposition, and the chance left at the stored number.
    FROM OPERATOR QUESTION 37 (ruled 2026-10-05) this world's recommendation
    buys the home side -- the other side of the model's words -- and the
    card and the row headline it (54c against 48.5c), so the price planted
    is the away side's, the side the card's words no longer name.
    """
    import json as _json

    from gridiron import audit as _audit, correction as _correction
    from gridiron import shortlist as _shortlist, views as _views
    from gridiron.market import recommend as _recommend
    from gridiron.priced import coverage as _coverage

    guard = "audit.board_price_side_faults"
    violation = "a priced board row off its card's corrected number, or priced on the other side"
    dist = {"quantity": "home_margin", "family": "normal", "mean": 2.0, "sd": 13.0,
            "declared": "2026-08-31T00:00:00Z", "written_blind": True}
    whole = _json.dumps({"coverage": 1.0, "margin_distribution": dist})
    missed, first = [], None
    saved_priceable, saved_card = _coverage.priceable, _views._today_card
    with tempfile.TemporaryDirectory(ignore_cleanup_errors=True) as tmp:
        conn = db.open_db(Path(tmp) / "priced.db")
        try:
            _coverage.priceable = lambda conn, sport, market, **_: {
                "priceable": True, "market": market, "why": "covered, in this planting"}
            conn.execute(
                "INSERT INTO games (id, sport, season, week, game_type, home, away,"
                " kickoff_utc, status, league_date) VALUES ('g0', 'mlb', 2026, 1,"
                " 'R', 'AAA', 'BBB', '2099-01-01T00:00:00Z', 'scheduled', '2026-09-08')")
            conn.execute(
                "INSERT INTO predictions (created_utc, sport, game_id, market_type,"
                " subject, line_asked, model_prob, model_side, predictor, pass_kind,"
                " factor_set_version, factors_json, reasoning) VALUES"
                " ('2026-09-07T00:00:00Z', 'mlb', 'g0', 'moneyline', 'BBB', NULL,"
                " 0.57, 'win', 'statistical', 'final', 'fs2', ?, 'planting')", (whole,))
            pid = conn.execute("SELECT MAX(id) FROM predictions").fetchone()[0]
            claimed = "2026-09-07T01:30:00Z"
            conn.execute(
                "INSERT INTO market_snapshots (prediction_id, fetched_utc, source,"
                " implied_prob, kind) VALUES (?, ?, 'planting', 0.485, 'open_at_predict')",
                (pid, claimed))
            conn.execute(
                "INSERT INTO venue_quotes (venue, ticker, event_ticker, sport, game_id,"
                " market, quantity, line, yes_side, yes_bid, yes_ask, fetched_utc)"
                " VALUES ('kalshi', 't0', 'e', 'mlb', 'g0', 'moneyline', 'home_win',"
                " NULL, 'home', 0.475, 0.495, ?)", (claimed,))
            quote = conn.execute("SELECT MAX(id) FROM venue_quotes").fetchone()[0]
            conn.execute(
                "INSERT INTO at_the_line_claims (prediction_id, quote_id, venue, sport,"
                " game_id, market, quantity, line, side, shape, dist_mean, dist_sd,"
                " model_prob, venue_price, venue_implied, price_basis, created_utc)"
                " VALUES (?, ?, 'kalshi', 'mlb', 'g0', 'moneyline', 'home_win', NULL,"
                " 'home', 'line_less', NULL, NULL, 0.43, 0.485, 0.485, 'mid', ?)",
                (pid, quote, claimed))
            conn.commit()
            _shortlist.rank_rows(conn, [pid])
            version = _correction.record_fit(
                conn, sport="mlb", market_type="moneyline", forecaster="statistical",
                model=_correction.Platt(slope=0.449, intercept=-0.270, n_train=106),
                status="planting", fitted_utc="2026-09-01T00:00:00Z")
            fid = conn.execute(
                "SELECT id FROM calibration_corrections WHERE version = ? AND"
                " sport = 'mlb' AND market_type = 'moneyline' AND forecaster ="
                " 'statistical'", (version,)).fetchone()[0]
            _correction.activate_in_a_scratch_world(conn, fid, now="2026-09-01T00:00:00Z")

            def block_of(payload):
                return next(q for g in payload["board"]["games"] for q in g["questions"]
                            if q["prediction_id"] == pid)

            # THE SIDE THE CARD'S WORDS NAME (operator question 37, ruled
            # 2026-10-05: "headline the contract the recommendation buys").
            # The corrected 53.58% against 48.5c makes the home side, AAA, the
            # one bought -- the other side of the model's "BBB to win" -- so
            # the card and the row headline AAA at its corrected number and
            # its price; until the ruling they named BBB at 46.42% and 51.5c.
            shipped = _views.week(conn, "mlb", 2026, 1)
            faults = _audit.board_price_side_faults(shipped)
            got = block_of(shipped)
            if faults or abs(got["prob"] - 0.5358) > 1e-3 or abs(got["price"] - 0.485) > 1e-9:
                missed.append(f"the shipped row is not the card's numbers on the side "
                              f"its words name, the home side bought ({got.get('prob')}, "
                              f"{got.get('price')}): "
                              + (faults[0] if faults else "no fault named"))

            def as_merged(*args, **kwargs):
                out = saved_card(*args, **kwargs)
                out.pop("fair_value", None)
                out.pop("question_takes_the_proposition", None)
                return out

            # FROM 2026-09-30 THE PAGE REFUSES THE MERGE'S SHAPE ITSELF: a
            # priced card with no placed side is not drawn (the operator's
            # ruling of 2026-09-30), so the builder raises by name where the
            # merge drew 57% beside the home side's 48c. Either answer -- the
            # refusal, or a payload the check names -- catches it; a payload
            # drawn and passed does not.
            _views._today_card = as_merged
            try:
                merged = _views.week(conn, "mlb", 2026, 1)
            except Exception as exc:  # noqa: BLE001 - which refusal is the point
                if type(exc).__name__ != "UnplaceableSide":
                    raise
                merged = None
            _views._today_card = saved_card
            if merged is None:
                # THE PAYLOAD THE MERGE PRODUCED, for the check: the card
                # without its two numbers, the row at the stored 57% and 48.5c.
                merged = _views.week(conn, "mlb", 2026, 1)
                card = next(c for c in merged["today"]["clears"] + merged["today"]["watching"]
                            if c["prediction_id"] == pid)
                card.pop("fair_value", None)
                card.pop("question_takes_the_proposition", None)
                block = block_of(merged)
                block.update({"prob": 0.57, "prob_words": "57%", "price": 0.485,
                              "pays": _recommend.payout_multiple(0.485)})
            forms = {"the card without its corrected number (the merge's shape)": merged}
            left = _views.week(conn, "mlb", 2026, 1)
            block = block_of(left)
            # the other side's: the away side's 51.5c, where the card's words
            # name the home side from operator question 37 (it was the
            # proposition's 48.5c under the away side's words until then)
            block["price"], block["pays"] = 0.515, _recommend.payout_multiple(0.515)
            forms["the price and payout left on the side its words do not name"] = left
            stored = _views.week(conn, "mlb", 2026, 1)
            block = block_of(stored)
            block["prob"], block["prob_words"] = 0.57, "57%"
            forms["the chance left at the stored number"] = stored
            for name, planted in forms.items():
                faults = _audit.board_price_side_faults(planted)
                if not faults:
                    missed.append(f"{name} passed")
                elif first is None:
                    first = faults[0]
            try:
                _audit.check_the_board_prices_the_side_it_names(merged)
                missed.append("the check raised nothing on the merge's shape")
            except _audit.LawViolation:
                pass
        finally:
            _coverage.priceable = saved_priceable
            _views._today_card = saved_card
            conn.close()
    if not _step_2_calls("check_the_board_prices_the_side_it_names"):
        missed.append("the gate's step 2 does not call "
                      "`audit.check_the_board_prices_the_side_it_names`")
    if missed:
        return Result(LAW_CARDS, violation, guard, False, "NOT CAUGHT - " + " | ".join(missed))
    return Result(LAW_CARDS, violation, guard, True, first or "")


# ---------------------------------------------------------------------------
# THE SIDE IS PLACED IN ONE PLACE, AND A SIDE IT CANNOT PLACE IS REFUSED
# (the operator's ruling of 2026-09-30, docs/briefs/2026-09-30-rulings.md)
# ---------------------------------------------------------------------------
#
# "Rec 111 / NCAAF wrong side: fix it ... Read 'fail to cover' as the no side
# in the one place the side is worked out; the page and the check refuse any
# side they can't place instead of passing it; planting." Recommendation 111,
# stored correctly as the no side of "TLSA covers +6.5" (0.2398 for Tulsa
# covering, a 48.5c yes price), was drawn "North Texas -6.5 · 24% · 48¢":
# the other side's numbers, because `priced.shape.blind_probability` had no
# rule for college football's "fail to cover" and the page and the gate's
# check turned only on `is False`. Three plantings, each on rec 111's shape.

LAW_THE_SIDE_IS_PLACED = ("A NUMBER IS SHOWN ONLY ON A SIDE THE ONE PLACE CAN "
                          "PLACE, AND ON THAT SIDE")


def _rec_111_world(path: Path, side: str):
    """Rec 111's shape on a scratch file: UNT at TLSA, the final pass on
    "TLSA covers +6.5" answered on `side` at 62.6%, a claim of 0.2398 for the
    home side covering against a 48.5c yes price, on the shortlist."""
    import json as _json

    from gridiron import shortlist as _shortlist

    dist = {"quantity": "home_margin", "family": "normal", "mean": -9.0, "sd": 14.0,
            "declared": "2026-08-31T00:00:00Z", "written_blind": True}
    conn = db.open_db(path)
    conn.execute(
        "INSERT INTO games (id, sport, season, week, game_type, home, away,"
        " kickoff_utc, status, league_date) VALUES ('401862786', 'cfb', 2026,"
        " 20261001, 'REG', 'TLSA', 'UNT', '2099-10-02T01:00:00Z', 'scheduled',"
        " '2026-10-01')")
    conn.execute(
        "INSERT INTO predictions (created_utc, sport, game_id, market_type,"
        " subject, line_asked, model_prob, model_side, predictor, pass_kind,"
        " factor_set_version, factors_json, reasoning) VALUES"
        " ('2026-09-28T15:00:00Z', 'cfb', '401862786', 'spread', 'TLSA', 6.5,"
        " 0.626036, ?, 'statistical', 'final', 'fs2', ?, 'planting')",
        (side, _json.dumps({"coverage": 1.0, "margin_distribution": dist})))
    pid = conn.execute("SELECT MAX(id) FROM predictions").fetchone()[0]
    conn.execute(
        "INSERT INTO venue_quotes (venue, ticker, event_ticker, sport, game_id,"
        " market, quantity, line, yes_side, yes_bid, yes_ask, fetched_utc)"
        " VALUES ('kalshi', 't111', 'e', 'cfb', '401862786', 'spread',"
        " 'home_margin', 6.5, 'home', 0.475, 0.495, '2026-09-28T15:00:44Z')")
    quote = conn.execute("SELECT MAX(id) FROM venue_quotes").fetchone()[0]
    conn.execute(
        "INSERT INTO at_the_line_claims (prediction_id, quote_id, venue, sport,"
        " game_id, market, quantity, line, side, shape, dist_mean, dist_sd,"
        " model_prob, venue_price, venue_implied, price_basis, created_utc)"
        " VALUES (?, ?, 'kalshi', 'cfb', '401862786', 'spread', 'home_margin',"
        " 6.5, 'home', 'rung_differs_margin', -9.0, 14.0, 0.2398, 0.485, 0.485,"
        " 'mid', '2026-09-28T15:00:45Z')", (pid, quote))
    conn.commit()
    _shortlist.rank_rows(conn, [pid])
    return conn, pid


def _rec_111_block(payload, pid):
    return next(q for g in payload["board"]["games"] for q in g["questions"]
                if q["prediction_id"] == pid)


def _unplaced_nfl_world(path: Path, *, market: str, subject: str, line, side: str,
                        predictor: str, status: str, prop_type: str | None = None):
    """THE PROVER'S TWO FORMS (2026-09-30): one NFL game with a well-spelled
    question of the page's forecaster on it, so the row exists, and the
    question under test stored on `side` -- unpriced, so no number but the
    model's own could stand beside it."""
    from gridiron import shortlist as _shortlist

    played = status != "scheduled"
    conn = db.open_db(path)
    conn.execute(
        "INSERT INTO games (id, sport, season, week, game_type, home, away,"
        " kickoff_utc, status, league_date, home_score, away_score) VALUES"
        " ('g1', 'nfl', 2026, 5, 'REG', 'HOM', 'AWY', ?, ?, '2026-09-28', ?, ?)",
        ("2026-09-28T17:00:00Z" if played else "2099-10-05T17:00:00Z", status,
         27 if played else None, 20 if played else None))
    conn.execute(
        "INSERT INTO predictions (created_utc, sport, game_id, market_type,"
        " subject, line_asked, model_prob, model_side, predictor, pass_kind,"
        " factor_set_version, factors_json, reasoning) VALUES"
        " ('2026-09-28T15:00:00Z', 'nfl', 'g1', 'total', 'AWY @ HOM', 41.5, 0.6,"
        " 'over', 'statistical', 'early', 'fs2', '{}', 'planting')")
    conn.execute(
        "INSERT INTO predictions (created_utc, sport, game_id, market_type,"
        " subject, line_asked, model_prob, model_side, predictor, pass_kind,"
        " factor_set_version, factors_json, reasoning, prop_type, outcome,"
        " resolved_utc) VALUES ('2026-09-28T15:00:01Z', 'nfl', 'g1', ?, ?, ?, 0.62,"
        " ?, ?, 'final', 'fs3', '{}', 'planting', ?, ?, ?)",
        (market, subject, line, side, predictor, prop_type,
         1 if status == "final" else None,
         "2026-09-28T21:00:00Z" if status == "final" else None))
    pid = conn.execute("SELECT MAX(id) FROM predictions").fetchone()[0]
    conn.commit()
    _shortlist.rank_rows(conn, [pid - 1, pid])
    return conn, pid


def plant_a_side_the_one_place_does_not_know_shown_with_numbers() -> Result:
    """Rec 111's shape with its side spelled "fails to cover" -- a spelling no
    sport declares and the one place does not know, as "fail to cover" was
    to the numbers until 2026-09-30.

    On the released code the page draws it -- the claim's own 24% and 48c
    under the words of the side the words guessed -- and nothing in the gate
    asks whether a stored side can be placed. CAUGHT means: the page refuses
    it by name (`subjects.UnplaceableSide`, the API's 500), and the gate's
    `audit.check_every_side_is_placed` fails on the record that holds it,
    called from step 2.

    AND TWO FORMS FROM ITS PROVER (2026-09-30), each drawn with a number by
    the build as first written, where the page must refuse by name: an EMPTY
    stored side on an unpriced total ("over 44.5 total points · 62%": the
    words read '' as "no side, said as asked"), and the OTHER forecaster's
    prop stored "Over" on a finished game ("Some Player Over 55.5 receiving
    yards · 62%": its card is built from `language.phrase` alone, whose prop
    branch printed an unknown spelling as itself).
    """
    from gridiron import views as _views
    from gridiron.priced import coverage as _coverage

    guard = "subjects.side_taken (the page refuses) + audit.check_every_side_is_placed"
    violation = "a stored side the one place cannot place, drawn with numbers"
    missed, first = [], None
    saved = _coverage.priceable
    with tempfile.TemporaryDirectory(ignore_cleanup_errors=True) as tmp:
        try:
            _coverage.priceable = lambda conn, sport, market, **_: {
                "priceable": True, "market": market, "why": "covered, in this planting"}
            # THE PROVER'S FORMS, each on a world of its own.
            for label, spec in (
                    ("an empty stored side on an unpriced total",
                     {"market": "total", "subject": "AWY @ HOM", "line": 44.5, "side": "",
                      "predictor": "statistical", "status": "scheduled"}),
                    ("the other forecaster's prop stored 'Over' on a finished game",
                     {"market": "prop", "subject": "Some Player receiving_yards",
                      "line": 55.5, "side": "Over", "predictor": "llm",
                      "status": "final", "prop_type": "receiving_yards"})):
                form_conn, form_pid = _unplaced_nfl_world(
                    Path(tmp) / f"form-{spec['market']}.db", **spec)
                try:
                    payload = _views.week(form_conn, "nfl", 2026, 5,
                                          forecaster="statistical")
                    drawn = [q for g in payload["board"]["games"]
                             for q in g["questions"] if q["prediction_id"] == form_pid]
                    missed.append(
                        f"{label}: the page drew it with a number: "
                        + "; ".join(f"{q.get('question')!r} at {q.get('prob_words')!r}"
                                    for q in drawn))
                except Exception as exc:  # noqa: BLE001 - which refusal is the point
                    if (type(exc).__name__ != "UnplaceableSide"
                            or repr(spec["side"]) not in str(exc)):
                        missed.append(f"{label}: the page failed, but not by name: {exc!r}")
                form_conn.close()
            conn, pid = _rec_111_world(Path(tmp) / "unknown.db", "fails to cover")
            try:
                payload = _views.week(conn, "cfb", 2026, 20261001)
                block = _rec_111_block(payload, pid)
                missed.append(
                    f"the page drew the unplaceable side with numbers: "
                    f"{block.get('question')!r} at {block.get('prob_words')!r}, "
                    f"price {block.get('price')!r}, pays {block.get('pays')!r}")
            except Exception as exc:  # noqa: BLE001 - which refusal is the point
                if type(exc).__name__ != "UnplaceableSide" or "fails to cover" not in str(exc):
                    missed.append(f"the page failed, but not by name: {exc!r}")
                else:
                    first = str(exc)
            placed = getattr(audit, "check_every_side_is_placed", None)
            if placed is None:
                missed.append("the gate has no check that every stored side is placed")
            else:
                try:
                    placed(conn)
                    missed.append("audit.check_every_side_is_placed passed a record "
                                  "holding 'fails to cover'")
                except audit.LawViolation as exc:
                    if "fails to cover" not in str(exc):
                        missed.append(f"the check failed without naming the side: {exc}")
            conn.close()
        finally:
            _coverage.priceable = saved
    if not _step_2_calls("check_every_side_is_placed"):
        missed.append("the gate's step 2 does not call `audit.check_every_side_is_placed`")
    if missed:
        return Result(LAW_THE_SIDE_IS_PLACED, violation, guard, False,
                      "NOT CAUGHT - " + " | ".join(missed))
    return Result(LAW_THE_SIDE_IS_PLACED, violation, guard, True, first or "")


def plant_rec_111_painted_on_the_other_sides_numbers() -> Result:
    """Rec 111's row drawn on Tulsa's numbers -- 24%, 48c, 2.06x -- under
    "North Texas -6.5", exactly as the released page drew it.

    On the released code the check held the row to its card, and the card
    could not place its side, so the other side's numbers passed. CAUGHT
    means: the shipped row is North Texas's own numbers (about 76% and
    51.5c), and the same row painted on Tulsa's is named by
    `audit.board_price_side_faults`.
    """
    from gridiron import views as _views
    from gridiron.market import recommend as _recommend
    from gridiron.priced import coverage as _coverage

    guard = "audit.board_price_side_faults"
    violation = "a priced row painted with the other side's chance, price and payout"
    missed, first = [], None
    saved = _coverage.priceable
    with tempfile.TemporaryDirectory(ignore_cleanup_errors=True) as tmp:
        try:
            _coverage.priceable = lambda conn, sport, market, **_: {
                "priceable": True, "market": market, "why": "covered, in this planting"}
            conn, pid = _rec_111_world(Path(tmp) / "painted.db", "fail to cover")
            shipped = _views.week(conn, "cfb", 2026, 20261001)
            got = _rec_111_block(shipped, pid)
            if (got.get("prob") is None or abs(got["prob"] - 0.7602) > 1e-4
                    or got.get("price") is None or abs(got["price"] - 0.515) > 1e-9):
                missed.append(f"the shipped row is not North Texas's own numbers: "
                              f"{got.get('prob_words')!r} at {got.get('price')!r}")
            painted = _views.week(conn, "cfb", 2026, 20261001)
            block = _rec_111_block(painted, pid)
            block.update({"prob": 0.2398, "prob_words": "24%", "price": 0.485,
                          "pays": _recommend.payout_multiple(0.485)})
            faults = audit.board_price_side_faults(painted)
            if not faults:
                missed.append("the row painted on Tulsa's 24%, 48c and 2.06x passed")
            else:
                first = faults[0]
            conn.close()
        finally:
            _coverage.priceable = saved
    if missed:
        return Result(LAW_THE_SIDE_IS_PLACED, violation, guard, False,
                      "NOT CAUGHT - " + " | ".join(missed))
    return Result(LAW_THE_SIDE_IS_PLACED, violation, guard, True, first or "")


def plant_an_unplaceable_side_the_check_passes() -> Result:
    """A priced Today card whose side could not be placed
    (`question_takes_the_proposition` None) and a board row agreeing with its
    unturned numbers: rec 111 as the released payload carried it.

    On the released code the check read `is False` and passed it. CAUGHT
    means `audit.board_price_side_faults` names it and
    `audit.check_the_board_prices_the_side_it_names` raises.

    AND A LIVE ROW (the prover's form, 2026-09-30): rec 88's live card as the
    released page carried it -- the claim's "pregame 43%" beside "Army covers
    +0.5", its side not placed -- which the check, walking only the priced
    upcoming blocks, passed even as first built.
    """
    guard = "audit.board_price_side_faults"
    violation = "the gate's check passing a priced side nobody can place"
    payload = {
        "forecaster": "statistical",
        "today": {"clears": [{"prediction_id": 3147, "state": "upcoming",
                              "model_words": "24¢", "fair_value": 0.2398,
                              "question_takes_the_proposition": None,
                              "price": 0.485, "payout": 2.062}]},
        "board": {"games": [{"questions": [{
            "prediction_id": 3147, "state": "upcoming", "forecaster": "statistical",
            "prob": 0.2398, "prob_words": "24%", "price": 0.485, "pays": 2.062}]}]}}
    live = {
        "forecaster": "statistical",
        "today": {"live": [{"prediction_id": 2478, "state": "live",
                            "pregame_words": "pregame 43%",
                            "question_takes_the_proposition": None}]},
        "board": {"games": [{"questions": [{
            "prediction_id": 2478, "state": "live", "forecaster": "statistical",
            "pregame_words": "pregame 43%"}]}]}}
    missed = []
    faults = audit.board_price_side_faults(payload)
    if not faults:
        missed.append("board_price_side_faults passed a priced card whose side is None")
    try:
        audit.check_the_board_prices_the_side_it_names(payload)
        missed.append("the check raised nothing")
    except audit.LawViolation:
        pass
    if not audit.board_price_side_faults(live):
        missed.append("board_price_side_faults passed a live card's pregame figure "
                      "whose side is None (rec 88's live row)")
    if missed:
        return Result(LAW_THE_SIDE_IS_PLACED, violation, guard, False,
                      "NOT CAUGHT - " + " | ".join(missed))
    return Result(LAW_THE_SIDE_IS_PLACED, violation, guard, True, faults[0])


# ---------------------------------------------------------------------------
# EVERY PICK NAMES ITS OWN SIDE: THE PAYOUT, THE RECOMMENDATION LINE AND MY
# DAY (pick-number step C, 2026-09-30; the queue rule as amended that day)
# ---------------------------------------------------------------------------
#
# The reading taken (docs/REPAIR_STATE.md): a number on a pick is always
# stated under the words of the exact contract it belongs to -- its line and
# its side. Three places stated another side's number, or club, under a
# pick's words (the wrong-side fix's builder and prover, 2026-09-30): the
# Today card's payout (finding 3), the recommendation line (finding 4) and
# My day's chip (finding 6); and the sweep found the payout floor folding by
# the proposition's payout. Each is planted as the released code (fa4c8eb)
# ships it, on a scratch world, and must be refused by
# `audit.pick_side_faults`, which gate step 2 calls on every sport's slate.

LAW_THE_PICK_NAMES_ITS_SIDE = ("A NUMBER ON A PICK IS STATED UNDER THE WORDS OF "
                               "THE SIDE IT BELONGS TO")


def _pick_side_moneyline_world(path: Path, *, price: float):
    """The board-merge prover's world: BBB (away) to win at 57%, a claim of
    43% on the home side AAA against a home price of `price`, on the
    shortlist, the game in 2099."""
    import json as _json

    from gridiron import shortlist as _shortlist

    dist = {"quantity": "home_margin", "family": "normal", "mean": 2.0, "sd": 13.0,
            "declared": "2026-08-31T00:00:00Z", "written_blind": True}
    conn = db.open_db(path)
    conn.execute(
        "INSERT INTO games (id, sport, season, week, game_type, home, away,"
        " kickoff_utc, status, league_date) VALUES ('g0', 'mlb', 2026, 1,"
        " 'R', 'AAA', 'BBB', '2099-01-01T00:00:00Z', 'scheduled', '2026-09-08')")
    conn.execute(
        "INSERT INTO predictions (created_utc, sport, game_id, market_type,"
        " subject, line_asked, model_prob, model_side, predictor, pass_kind,"
        " factor_set_version, factors_json, reasoning) VALUES"
        " ('2026-09-07T00:00:00Z', 'mlb', 'g0', 'moneyline', 'BBB', NULL,"
        " 0.57, 'win', 'statistical', 'final', 'fs2', ?, 'planting')",
        (_json.dumps({"coverage": 1.0, "margin_distribution": dist}),))
    pid = conn.execute("SELECT MAX(id) FROM predictions").fetchone()[0]
    claimed = "2026-09-07T01:30:00Z"
    conn.execute(
        "INSERT INTO market_snapshots (prediction_id, fetched_utc, source,"
        " implied_prob, kind) VALUES (?, ?, 'planting', ?, 'open_at_predict')",
        (pid, claimed, price))
    conn.execute(
        "INSERT INTO venue_quotes (venue, ticker, event_ticker, sport, game_id,"
        " market, quantity, line, yes_side, yes_bid, yes_ask, fetched_utc)"
        " VALUES ('kalshi', 't0', 'e', 'mlb', 'g0', 'moneyline', 'home_win',"
        " NULL, 'home', ?, ?, ?)", (price - 0.01, price + 0.01, claimed))
    quote = conn.execute("SELECT MAX(id) FROM venue_quotes").fetchone()[0]
    conn.execute(
        "INSERT INTO at_the_line_claims (prediction_id, quote_id, venue, sport,"
        " game_id, market, quantity, line, side, shape, dist_mean, dist_sd,"
        " model_prob, venue_price, venue_implied, price_basis, created_utc)"
        " VALUES (?, ?, 'kalshi', 'mlb', 'g0', 'moneyline', 'home_win', NULL,"
        " 'home', 'line_less', NULL, NULL, 0.43, ?, ?, 'mid', ?)",
        (pid, quote, price, price, claimed))
    conn.commit()
    _shortlist.rank_rows(conn, [pid])
    return conn, pid


def _pick_side_check(payload, name: str, missed: list, want: str):
    """Ask the step's check about a planted payload: named, or missed."""
    scan = getattr(audit, "pick_side_faults", None)
    if scan is None:
        missed.append(f"{name}: the gate has no check that a pick names its own side")
        return None
    faults = scan(payload)
    if not any(want in f for f in faults):
        missed.append(f"{name} passed" + (f" (named only: {faults[0]})" if faults else ""))
        return None
    try:
        audit.check_every_pick_names_its_side(payload)
        missed.append(f"{name}: the check raised nothing")
    except audit.LawViolation:
        pass
    return next(f for f in faults if want in f)


def plant_a_payout_on_the_propositions_side() -> Result:
    """The Today card's payout and payout words left on the claim's fixed
    proposition under a question naming the other side, and the payout floor
    folding by the proposition's payout.

    AS RELEASED (fa4c8eb): "BBB to win" at a 48.5c home price reads "52¢ ·
    pays 1.94x" in its venue words and says 2.062 and "2.06x" -- the home
    side's -- as its payout and payout words (pick-number finding 3); and
    under a 2.0x floor it is shown above the floor, on the home side's 2.06x,
    where the side it buys pays 1.94x (the sweep). CAUGHT means: the shipped
    card says 1.942 and "1.94x" and is folded, both released shapes are named
    by `audit.pick_side_faults`, and the gate's step 2 makes the call.
    """
    from gridiron import settings as _settings, views as _views
    from gridiron.market import recommend as _recommend
    from gridiron.priced import coverage as _coverage

    guard = "audit.pick_side_faults"
    violation = "a payout of the other side on a pick, or a fold by another side's payout"
    missed, first = [], None
    saved = _coverage.priceable
    with tempfile.TemporaryDirectory(ignore_cleanup_errors=True) as tmp:
        try:
            _coverage.priceable = lambda conn, sport, market, **_: {
                "priceable": True, "market": market, "why": "covered, in this planting"}
            conn, pid = _pick_side_moneyline_world(Path(tmp) / "payout.db", price=0.485)
            _settings.set_value(conn, "min_payout", "2.0")

            def card_of(payload):
                return next((c for group in ("clears", "below_floor", "watching")
                             for c in payload["today"][group] if c["prediction_id"] == pid),
                            None)

            shipped = _views.week(conn, "mlb", 2026, 1)
            card = card_of(shipped)
            want = _recommend.payout_multiple(1.0 - 0.485)
            if card is None or card.get("payout") != want or card.get("payout_words") != "1.94x":
                missed.append(f"the shipped card says {card and card.get('payout')!r} "
                              f"and {card and card.get('payout_words')!r} where BBB "
                              f"to win pays {want!r}")
            if pid not in {c["prediction_id"] for c in shipped["today"]["below_floor"]}:
                missed.append("the shipped card is not folded under the 2.0x floor, "
                              "where the side it buys pays 1.94x")
            released = _views.week(conn, "mlb", 2026, 1)
            planted = card_of(released)
            planted.update({"payout": _recommend.payout_multiple(0.485),
                            "payout_words": "2.06x"})
            first = _pick_side_check(released, "the proposition's payout on the turned card",
                                     missed, "finding 3")
            folded = _views.week(conn, "mlb", 2026, 1)
            today = folded["today"]
            today["clears"] = today["clears"] + today["below_floor"]
            today["below_floor"] = []
            _pick_side_check(folded, "the pick shown above the floor on the home side's "
                                     "payout", missed, "shown above")
            conn.close()
        finally:
            _coverage.priceable = saved
    if not _step_2_calls("check_every_pick_names_its_side"):
        missed.append("the gate's step 2 does not call "
                      "`audit.check_every_pick_names_its_side`")
    if missed:
        return Result(LAW_THE_PICK_NAMES_ITS_SIDE, violation, guard, False,
                      "NOT CAUGHT - " + " | ".join(missed))
    return Result(LAW_THE_PICK_NAMES_ITS_SIDE, violation, guard, True, first or "")


def plant_a_recommendation_line_on_the_proposition() -> Result:
    """A recommendation line stating the proposition's number and price
    after the question's words, and calling the side it buys "the yes side"
    or "the other side".

    AS RELEASED (fa4c8eb), on two worlds: the recommendation buys the side
    the words name (BBB, at 51.5c) and the line read "BBB to win -- the model
    makes it 43¢, the venue is at 48¢, and the other side is worth ..."; and
    it buys the OTHER side of the words (AAA at 30c, as recs 47 and 82 on the
    record did) and the line still named BBB. CAUGHT means: the shipped lines
    name the side each buys with that side's number and price -- "BBB to win
    -- ... 57¢ ... 52¢" and "AAA to win -- ... 43¢ ... 30¢" -- and the
    released lines are named by `audit.pick_side_faults`.
    """
    from gridiron import views as _views
    from gridiron.priced import coverage as _coverage

    guard = "audit.pick_side_faults"
    violation = "a recommendation line on the proposition's numbers, calling its side 'the other side'"
    missed, first = [], None
    saved = _coverage.priceable
    released_words = {
        0.485: ("BBB to win — the model makes it 43¢, the venue is at 48¢, and the "
                "other side is worth +3.5¢ a contract after the fee."),
        0.30: ("BBB to win — the model makes it 43¢, the venue is at 30¢, and the "
               "yes side is worth +11.0¢ a contract after the fee."),
    }
    shipped_head = {
        0.485: "BBB to win — the model makes it 57¢, the venue is at 52¢, and it is worth",
        0.30: "AAA to win — the model makes it 43¢, the venue is at 30¢, and it is worth",
    }
    with tempfile.TemporaryDirectory(ignore_cleanup_errors=True) as tmp:
        try:
            _coverage.priceable = lambda conn, sport, market, **_: {
                "priceable": True, "market": market, "why": "covered, in this planting"}
            for price, planted_words in released_words.items():
                conn, pid = _pick_side_moneyline_world(Path(tmp) / f"line{price}.db",
                                                       price=price)
                shipped = _views.week(conn, "mlb", 2026, 1)
                line = next((x for x in shipped["recommendations"]["lines"]
                             if x["prediction_id"] == pid), None)
                if line is None or not str(line.get("words")).startswith(shipped_head[price]):
                    missed.append(f"at {price}: the shipped line reads "
                                  f"{line and line.get('words')!r}")
                released = _views.week(conn, "mlb", 2026, 1)
                for x in released["recommendations"]["lines"]:
                    if x["prediction_id"] == pid:
                        for key in ("side_words", "fair_value", "price"):
                            x.pop(key, None)
                        x["words"] = planted_words
                got = _pick_side_check(released, f"the released line at {price}", missed,
                                       "finding 4")
                first = first or got
                conn.close()
        finally:
            _coverage.priceable = saved
    if not _step_2_calls("check_every_pick_names_its_side"):
        missed.append("the gate's step 2 does not call "
                      "`audit.check_every_pick_names_its_side`")
    if missed:
        return Result(LAW_THE_PICK_NAMES_ITS_SIDE, violation, guard, False,
                      "NOT CAUGHT - " + " | ".join(missed))
    return Result(LAW_THE_PICK_NAMES_ITS_SIDE, violation, guard, True, first or "")


def plant_a_my_day_chip_wearing_the_subjects_club() -> Result:
    """A taken no-side game pick's My day chip wearing the club of its
    question's SUBJECT -- the home club -- beside the words of the side the
    model took.

    AS RELEASED (fa4c8eb): a taken "not_cover" on PHI -3.5 is the chip "PHI
    · DAL +3.5" and a taken "lose" moneyline "PHI · DAL to win" (pick-number
    finding 6; its prover's scratch world). CAUGHT means: the shipped chips
    wear DAL, and the released chips are named by `audit.pick_side_faults`.
    """
    from gridiron import shortlist as _shortlist, views as _views

    guard = "audit.pick_side_faults"
    violation = "a My day chip wearing the club its pick's words do not name"
    missed, first = [], None
    with tempfile.TemporaryDirectory(ignore_cleanup_errors=True) as tmp:
        conn = db.open_db(Path(tmp) / "day.db")
        conn.execute(
            "INSERT INTO games (id, sport, season, week, game_type, home, away,"
            " kickoff_utc, status, league_date) VALUES ('g1', 'nfl', 2026, 5,"
            " 'REG', 'PHI', 'DAL', '2099-10-05T17:00:00Z', 'scheduled', '2026-10-05')")
        ids = []
        for stamp, market, line, side in (("2026-09-28T15:00:00Z", "spread", -3.5, "not_cover"),
                                          ("2026-09-28T15:00:01Z", "moneyline", None, "lose")):
            conn.execute(
                "INSERT INTO predictions (created_utc, sport, game_id, market_type,"
                " subject, line_asked, model_prob, model_side, predictor, pass_kind,"
                " factor_set_version, factors_json, reasoning) VALUES (?, 'nfl', 'g1',"
                " ?, 'PHI', ?, 0.61, ?, 'statistical', 'final', 'fs3', '{}', 'planting')",
                (stamp, market, line, side))
            ids.append(conn.execute("SELECT MAX(id) FROM predictions").fetchone()[0])
        conn.commit()
        _shortlist.rank_rows(conn, ids)
        for pid in ids:
            conn.execute("INSERT INTO picks_taken (prediction_id, taken_utc) VALUES (?, ?)",
                         (pid, db.utcnow()))
        conn.commit()
        shipped = _views.week(conn, "nfl", 2026, 5)
        chips = {e["prediction_id"]: e for e in shipped["board"]["my_day"]["entries"]}
        worn = {pid: (chips.get(pid) or {}).get("club", {}).get("tricode") for pid in ids}
        if set(worn.values()) != {"DAL"}:
            missed.append(f"the shipped chips wear {sorted(set(map(str, worn.values())))} "
                          f"beside {[(chips.get(p) or {}).get('line_words') for p in ids]}")
        released = _views.week(conn, "nfl", 2026, 5)
        for e in released["board"]["my_day"]["entries"]:
            if e["prediction_id"] in ids:
                e["club"] = dict(e["club"], tricode="PHI")
        first = _pick_side_check(released, "the chips wearing PHI beside DAL's words",
                                 missed, "finding 6")
        conn.close()
    if not _step_2_calls("check_every_pick_names_its_side"):
        missed.append("the gate's step 2 does not call "
                      "`audit.check_every_pick_names_its_side`")
    if missed:
        return Result(LAW_THE_PICK_NAMES_ITS_SIDE, violation, guard, False,
                      "NOT CAUGHT - " + " | ".join(missed))
    return Result(LAW_THE_PICK_NAMES_ITS_SIDE, violation, guard, True, first or "")


def _step_2_hands_history_to(name: str) -> bool:
    """Does the gate's step 2 hand `views.history(...)` to `audit.<name>`,
    read from its syntax tree (the Results table's rows, 2026-09-30)?"""
    import ast as _ast

    gate = Path(audit.__file__).resolve().parents[1] / "tools" / "verify.py"
    step = next((node for node in _ast.parse(gate.read_text(encoding="utf-8")).body
                 if isinstance(node, _ast.FunctionDef) and node.name == "step_2_guards"),
                None)

    def is_history(node) -> bool:
        return (isinstance(node, _ast.Call) and isinstance(node.func, _ast.Attribute)
                and node.func.attr == "history"
                and isinstance(node.func.value, _ast.Name) and node.func.value.id == "views")

    return step is not None and any(
        isinstance(node, _ast.Call) and isinstance(node.func, _ast.Attribute)
        and node.func.attr == name and isinstance(node.func.value, _ast.Name)
        and node.func.value.id == "audit" and node.args and is_history(node.args[0])
        for node in _ast.walk(step))


def plant_a_results_row_naming_the_other_side() -> Result:
    """A Results row -- `views.history`, drawn in the Results table as
    "Prediction | ... | Model | Market then | ... | Result" -- whose words
    name the other side of the number beside them.

    AS RELEASED (fa4c8eb, and every release since the table was built;
    found by the step's prover, 2026-09-30, on a verified copy of the
    record): a history row carries no opponent, so `language.phrase` could
    not restate a no side as the other club, and its moneyline branch said
    the subject "to win" anyway -- "PHI to win" beside the model's 61% for
    PHI LOSING, the market's number for the same and the lose pick's
    verdict. 403 rows on the record, in every sport. CAUGHT means: the
    shipped rows say each side as asked ("PHI to lose", "PHI does not cover
    -3.5", "under 44.5 total points"), the released row is named by
    `audit.pick_side_faults`, and the gate's step 2 hands it every sport's
    history.
    """
    from gridiron import views as _views

    guard = "audit.pick_side_faults"
    violation = "a Results row naming the other side of its number"
    missed, first = [], None
    with tempfile.TemporaryDirectory(ignore_cleanup_errors=True) as tmp:
        conn = db.open_db(Path(tmp) / "results.db")
        conn.execute(
            "INSERT INTO games (id, sport, season, week, game_type, home, away,"
            " kickoff_utc, status, league_date) VALUES ('g1', 'nfl', 2026, 5,"
            " 'REG', 'PHI', 'DAL', '2099-10-05T17:00:00Z', 'scheduled', '2026-10-05')")
        ids = {}
        for stamp, market, subject, line, side in (
                ("2026-09-28T15:00:00Z", "moneyline", "PHI", None, "lose"),
                ("2026-09-28T15:00:01Z", "spread", "PHI", -3.5, "not_cover"),
                ("2026-09-28T15:00:02Z", "total", "DAL @ PHI", 44.5, "under")):
            conn.execute(
                "INSERT INTO predictions (created_utc, sport, game_id, market_type,"
                " subject, line_asked, model_prob, model_side, predictor, pass_kind,"
                " factor_set_version, factors_json, reasoning) VALUES (?, 'nfl', 'g1',"
                " ?, ?, ?, 0.61, ?, 'statistical', 'final', 'fs3', '{}', 'planting')",
                (stamp, market, subject, line, side))
            ids[market] = conn.execute("SELECT MAX(id) FROM predictions").fetchone()[0]
        conn.commit()
        want = {"moneyline": "PHI to lose", "spread": "PHI does not cover -3.5",
                "total": "under 44.5 total points"}
        shipped = _views.history(conn, sport="nfl", limit=50)
        said = {i["prediction_id"]: i["phrase"] for i in shipped["items"]}
        for market, pid in ids.items():
            if said.get(pid) != want[market]:
                missed.append(f"the shipped Results row of the {market} says "
                              f"{said.get(pid)!r} where its side reads {want[market]!r}")
        released = _views.history(conn, sport="nfl", limit=50)
        for item in released["items"]:
            if item["prediction_id"] == ids["moneyline"]:
                item["phrase"] = "PHI to win"
        first = _pick_side_check(released, "the lose row said 'PHI to win'", missed,
                                 "Results table")
        conn.close()
    if not _step_2_hands_history_to("check_every_pick_names_its_side"):
        missed.append("the gate's step 2 does not hand `views.history` to "
                      "`audit.check_every_pick_names_its_side`")
    if missed:
        return Result(LAW_THE_PICK_NAMES_ITS_SIDE, violation, guard, False,
                      "NOT CAUGHT - " + " | ".join(missed))
    return Result(LAW_THE_PICK_NAMES_ITS_SIDE, violation, guard, True, first or "")


def plant_an_edge_on_the_other_side_drawn_as_the_questions() -> Result:
    """An edge figure that is the OTHER side's, labelled on the Today card as
    the question's own and drawn bare on the board's tile.

    AS RELEASED (fa4c8eb; found by the step's prover, 2026-09-30): the
    figure is the better side's, and the card's label read `edge_side`,
    which is None when neither side clears the fee -- so "BBB to win" at 57%
    against 58c (AAA's yes price 42c) was labelled "Edge after fees" over
    -1.0c, which is AAA's; BBB's own is -3.0c. The board's tile draws the
    figure where the price is, with no label at all. On the record: ten
    cards, one upcoming that day (NBA 3166, "San Antonio to win", -1.5c
    where its own is -2.5c). CAUGHT means: the shipped card says "on the
    other side" and so does the tile, and both released shapes are named by
    `audit.pick_side_faults`.
    """
    from gridiron import views as _views
    from gridiron.priced import coverage as _coverage

    guard = "audit.pick_side_faults"
    violation = "the other side's edge drawn under the question's words"
    missed, first = [], None
    saved = _coverage.priceable
    with tempfile.TemporaryDirectory(ignore_cleanup_errors=True) as tmp:
        try:
            _coverage.priceable = lambda conn, sport, market, **_: {
                "priceable": True, "market": market, "why": "covered, in this planting"}
            conn, pid = _pick_side_moneyline_world(Path(tmp) / "edge.db", price=0.42)

            def card_of(payload):
                return next((c for group in ("clears", "below_floor", "watching")
                             for c in payload["today"][group] if c["prediction_id"] == pid),
                            None)

            def tile_of(payload):
                return next((q for g in payload["board"]["games"] for q in g["questions"]
                             if q["prediction_id"] == pid), None)

            shipped = _views.week(conn, "mlb", 2026, 1)
            card, tile = card_of(shipped), tile_of(shipped)
            if card is None or card.get("edge_words") != "-1.0¢" \
                    or not str(card.get("edge_label")).endswith("on the other side"):
                missed.append(f"the shipped card labels {card and card.get('edge_words')!r} "
                              f"{card and card.get('edge_label')!r} under 'BBB to win', "
                              f"where -1.0c is AAA's and BBB's own is -3.0c")
            if tile is None or tile.get("edge_words") != "-1.0¢ on the other side":
                missed.append(f"the shipped tile draws {tile and tile.get('edge_words')!r} "
                              f"beside {tile and tile.get('line_words')!r}")
            released = _views.week(conn, "mlb", 2026, 1)
            card_of(released)["edge_label"] = "Edge after fees"
            first = _pick_side_check(released, "the card labelling AAA's edge as BBB's",
                                     missed, "labels its")
            bare = _views.week(conn, "mlb", 2026, 1)
            tile_of(bare)["edge_words"] = "-1.0¢"
            _pick_side_check(bare, "the tile drawing AAA's edge bare beside BBB's words",
                             missed, "draws the edge")
            conn.close()
        finally:
            _coverage.priceable = saved
    if not _step_2_calls("check_every_pick_names_its_side"):
        missed.append("the gate's step 2 does not call "
                      "`audit.check_every_pick_names_its_side`")
    if missed:
        return Result(LAW_THE_PICK_NAMES_ITS_SIDE, violation, guard, False,
                      "NOT CAUGHT - " + " | ".join(missed))
    return Result(LAW_THE_PICK_NAMES_ITS_SIDE, violation, guard, True, first or "")


# ---------------------------------------------------------------------------
# A COMBO IS WORTH THE PRODUCT OF ITS PICKED SIDES, EACH LEG NAMED ON ITS
# PICKED SIDE (pick-number step B, 2026-09-30; the queue rule as amended that
# day)
# ---------------------------------------------------------------------------
#
# Finding 1 of the wrong-side fix's builder and prover: `combos.propose`
# multiplied each leg's `fair_value` -- the claim's fixed proposition's
# number -- whichever side the leg's recommendation buys, worked its ceiling
# out from that and priced its singles line off the yes price; and
# `views._proposal_card` named each leg in its question's words. On the
# record 34 of 35 proposals were drawn at a worth that was not their picked
# sides' product and 8 named a leg on the side it did not buy. Each is
# planted as the released code (8318650) ships it, on a scratch world, and
# must be refused by `audit.combo_side_faults`, which gate step 2 calls on
# every sport's slate. Its prover (the same day) added a third: legs named
# in their sides' words alone, without the game each is in, so two unders
# read alike.

LAW_THE_COMBO_IS_ITS_PICKED_SIDES = ("A PROPOSED COMBO IS WORTH THE PRODUCT OF ITS "
                                     "LEGS' PICKED SIDES, EACH LEG NAMED ON ITS SIDE")


def _combo_side_world(path: Path, legs):
    """Baseball moneylines on one slate, one question per game: the away
    side at 57%, so a claim of 43% on the home side, against the home price
    given; every question on the shortlist, every game in 2099. `legs` is
    [(game, home, away, price)]. At 48.5c a pick buys the away side (the
    claim's no side, the side its words name: 57% at 51.5c, +3.5c); at 30c
    it buys the home side (the claim's yes side, the OTHER side of its
    words: 43% at 30c, +11.0c), as recs 47 and 82 did."""
    import json as _json

    from gridiron import shortlist as _shortlist

    dist = {"quantity": "home_margin", "family": "normal", "mean": 2.0, "sd": 13.0,
            "declared": "2026-08-31T00:00:00Z", "written_blind": True}
    conn = db.open_db(path)
    ids = []
    claimed = "2026-09-07T01:30:00Z"
    for game, home, away, price in legs:
        conn.execute(
            "INSERT INTO games (id, sport, season, week, game_type, home, away,"
            " kickoff_utc, status, league_date) VALUES (?, 'mlb', 2026, 1,"
            " 'R', ?, ?, '2099-01-01T00:00:00Z', 'scheduled', '2026-09-08')",
            (game, home, away))
        conn.execute(
            "INSERT INTO predictions (created_utc, sport, game_id, market_type,"
            " subject, line_asked, model_prob, model_side, predictor, pass_kind,"
            " factor_set_version, factors_json, reasoning) VALUES"
            " ('2026-09-07T00:00:00Z', 'mlb', ?, 'moneyline', ?, NULL,"
            " 0.57, 'win', 'statistical', 'final', 'fs2', ?, 'planting')",
            (game, away, _json.dumps({"coverage": 1.0, "margin_distribution": dist})))
        pid = conn.execute("SELECT MAX(id) FROM predictions").fetchone()[0]
        conn.execute(
            "INSERT INTO market_snapshots (prediction_id, fetched_utc, source,"
            " implied_prob, kind) VALUES (?, ?, 'planting', ?, 'open_at_predict')",
            (pid, claimed, price))
        conn.execute(
            "INSERT INTO venue_quotes (venue, ticker, event_ticker, sport, game_id,"
            " market, quantity, line, yes_side, yes_bid, yes_ask, fetched_utc)"
            " VALUES ('kalshi', ?, 'e', 'mlb', ?, 'moneyline', 'home_win',"
            " NULL, 'home', ?, ?, ?)",
            (f"t{game}", game, price - 0.01, price + 0.01, claimed))
        quote = conn.execute("SELECT MAX(id) FROM venue_quotes").fetchone()[0]
        conn.execute(
            "INSERT INTO at_the_line_claims (prediction_id, quote_id, venue, sport,"
            " game_id, market, quantity, line, side, shape, dist_mean, dist_sd,"
            " model_prob, venue_price, venue_implied, price_basis, created_utc)"
            " VALUES (?, ?, 'kalshi', 'mlb', ?, 'moneyline', 'home_win', NULL,"
            " 'home', 'line_less', NULL, NULL, 0.43, ?, ?, 'mid', ?)",
            (pid, quote, game, price, price, claimed))
        ids.append(pid)
    conn.commit()
    _shortlist.rank_rows(conn, ids)
    return conn, ids


def _combo_side_check(payload, name: str, missed: list, want: str):
    """Ask step B's check about a planted payload: named, or missed."""
    scan = getattr(audit, "combo_side_faults", None)
    if scan is None:
        missed.append(f"{name}: the gate has no check that a combo is its legs' "
                      f"picked sides")
        return None
    faults = scan(payload)
    if not any(want in f for f in faults):
        missed.append(f"{name} passed" + (f" (named only: {faults[0]})" if faults else ""))
        return None
    try:
        audit.check_every_combo_is_its_picked_sides(payload)
        missed.append(f"{name}: the check raised nothing")
    except audit.LawViolation:
        pass
    return next(f for f in faults if want in f)


def plant_a_combo_worth_its_legs_yes_sides() -> Result:
    """A proposed combo worth the product of each leg's YES-side number, its
    ceiling and its singles line worked out from the yes sides.

    AS RELEASED (8318650): two legs, "BBB to win" and "DDD to win", each
    bought on the claim's no side (the away club, the side its words name:
    57% at 51.5c). The combo was worth 0.43 x 0.43 = 18%, "worth taking
    only below 16¢", and its singles line priced the home side at 48.5c --
    where the sides bought are worth 0.57 x 0.57 = 32% (pick-number finding
    1; on the record, "Rutgers covers -24.5 + Navy covers -6.5" at 2% for
    71.1%). CAUGHT means: the shipped combo is worth 0.3249 with the ceiling
    and singles line of the sides bought, each released shape -- the worth,
    the ceiling, the singles line, a leg's number -- is named by
    `audit.combo_side_faults`, and the gate's step 2 makes the call.
    """
    from gridiron import language as _language, views as _views
    from gridiron.market import combos as _combos
    from gridiron.priced import coverage as _coverage

    guard = "audit.combo_side_faults"
    violation = "a proposed combo worth the product of its legs' yes-side numbers"
    missed, first = [], None
    saved = _coverage.priceable
    with tempfile.TemporaryDirectory(ignore_cleanup_errors=True) as tmp:
        try:
            _coverage.priceable = lambda conn, sport, market, **_: {
                "priceable": True, "market": market, "why": "covered, in this planting"}
            conn, ids = _combo_side_world(
                Path(tmp) / "worth.db",
                [("g0", "AAA", "BBB", 0.485), ("g1", "CCC", "DDD", 0.485)])

            def proposal_of(payload):
                cards = ((payload.get("today") or {}).get("combos") or {}).get("cards") or []
                return cards[0] if cards else None

            shipped = _views.week(conn, "mlb", 2026, 1)
            card = proposal_of(shipped)
            if card is None or card.get("fair") != 0.3249:
                missed.append(f"the shipped combo is worth {card and card.get('fair')!r} "
                              f"where its legs' picked sides (BBB and DDD, 57% each) "
                              f"multiply to 0.3249")
            elif (getattr(audit, "combo_side_faults", None) is not None
                  and audit.combo_side_faults(shipped)):
                missed.append("the shipped combo is refused by the check: "
                              + audit.combo_side_faults(shipped)[0])
            yes_fair = _combos.fair_value([0.43, 0.43])
            yes_ceiling = _combos.price_ceiling(yes_fair)["ceiling_cents"]
            yes_singles = _combos.singles_alternative([0.485, 0.485], [0.43, 0.43])
            forms = (
                ("the worth the yes sides' product", "finding 1; LAW 5",
                 {"fair": yes_fair,
                  "fair_words": _language.price_chip_words(yes_fair * 100)}, None),
                ("the ceiling from the yes sides' product", "worth taking below",
                 {"ceiling_cents": yes_ceiling,
                  "ceiling_words": _language.combo_ceiling_words(yes_ceiling)}, None),
                ("the singles line on the yes price", "singles line on another side",
                 {"singles_words": _language.combo_singles_words(yes_singles),
                  "fee_ratio": yes_singles.get("ratio")}, None),
                ("a leg stating the proposition's number", "whose model number is",
                 {}, {"fair_cents": 43}),
            )
            for name, want, change, leg_change in forms:
                released = _views.week(conn, "mlb", 2026, 1)
                planted = proposal_of(released)
                if planted is None:
                    missed.append(f"{name}: the proposer made nothing to check")
                    continue
                planted.update(change)
                if leg_change:
                    planted["legs"][0].update(leg_change)
                got = _combo_side_check(released, name, missed, want)
                first = first or got
            conn.close()
        finally:
            _coverage.priceable = saved
    if not _step_2_calls("check_every_combo_is_its_picked_sides"):
        missed.append("the gate's step 2 does not call "
                      "`audit.check_every_combo_is_its_picked_sides`")
    if missed:
        return Result(LAW_THE_COMBO_IS_ITS_PICKED_SIDES, violation, guard, False,
                      "NOT CAUGHT - " + " | ".join(missed))
    return Result(LAW_THE_COMBO_IS_ITS_PICKED_SIDES, violation, guard, True, first or "")


def plant_a_combo_leg_named_on_the_side_it_does_not_buy() -> Result:
    """A proposed combo's leg named in its question's words where its
    recommendation buys the OTHER side of them.

    AS RELEASED (8318650): "DDD to win" at 57% against a 30c home price is
    bought as CCC to win (the claim's yes side, 43% at 30c, +11.0c), and the
    combo drew the leg "DDD to win" (pick-number finding 1; on the record 8
    of 35 proposals, e.g. "Rutgers covers -24.5" for a leg bought as Howard
    +24.5 and "Washington covers +1.5" for Detroit -1.5). CAUGHT means: the
    shipped combo names its legs "CCC to win" and "BBB to win" and is worth
    0.43 x 0.57, and the released leg is named by `audit.combo_side_faults`.
    """
    from gridiron import views as _views
    from gridiron.priced import coverage as _coverage

    guard = "audit.combo_side_faults"
    violation = "a combo leg named on the side it does not buy"
    missed, first = [], None
    saved = _coverage.priceable
    with tempfile.TemporaryDirectory(ignore_cleanup_errors=True) as tmp:
        try:
            _coverage.priceable = lambda conn, sport, market, **_: {
                "priceable": True, "market": market, "why": "covered, in this planting"}
            conn, ids = _combo_side_world(
                Path(tmp) / "words.db",
                [("g0", "AAA", "BBB", 0.485), ("g1", "CCC", "DDD", 0.30)])

            def proposal_of(payload):
                cards = ((payload.get("today") or {}).get("combos") or {}).get("cards") or []
                return cards[0] if cards else None

            shipped = _views.week(conn, "mlb", 2026, 1)
            card = proposal_of(shipped)
            words = sorted(str(leg.get("words")) for leg in (card or {}).get("legs") or [])
            # EACH ON ITS SIDE, AND IN ITS GAME (the prover of step B,
            # 2026-09-30: a leg names the game it is in).
            if (words != ["BBB to win · BBB at AAA", "CCC to win · DDD at CCC"]
                    or (card or {}).get("fair") != 0.2451):
                missed.append(f"the shipped combo names {words} worth "
                              f"{card and card.get('fair')!r}, where its legs are "
                              f"bought as BBB to win (57%) and CCC to win (43%)")
            released = _views.week(conn, "mlb", 2026, 1)
            planted = proposal_of(released)
            if planted is None:
                missed.append("the proposer made nothing to check")
            else:
                for leg in planted["legs"]:
                    if leg["prediction_id"] == ids[1]:
                        leg["words"] = "DDD to win"
                first = _combo_side_check(released, "the CCC leg named 'DDD to win'",
                                          missed, "side it does not buy")
            conn.close()
        finally:
            _coverage.priceable = saved
    if not _step_2_calls("check_every_combo_is_its_picked_sides"):
        missed.append("the gate's step 2 does not call "
                      "`audit.check_every_combo_is_its_picked_sides`")
    if missed:
        return Result(LAW_THE_COMBO_IS_ITS_PICKED_SIDES, violation, guard, False,
                      "NOT CAUGHT - " + " | ".join(missed))
    return Result(LAW_THE_COMBO_IS_ITS_PICKED_SIDES, violation, guard, True, first or "")


